// Get the input data
const inputData = $input.first().json;

// Check if there was an error from the HTTP request
if (inputData.error) {
  // Extract error details for logging
  const errorCode = inputData.error.code;
  const errorStatus = inputData.error.status;
  const errorMessage = inputData.error.message;

  // Check if it's a "customer not found" error (404 with NONEXISTENT_EXTERNAL_ID)
  const isNotFoundError = errorStatus === 404 && 
    (errorMessage.includes('NONEXISTENT_EXTERNAL_ID') || 
     errorMessage.includes('does not exist'));

  return {
    json: {
      customerExists: false,
      message: isNotFoundError 
        ? "Customer not found in NetSuite." 
        : "HTTP error occurred while checking customer",
      errorCode: errorCode,
      errorStatus: errorStatus,
      isNotFoundError: isNotFoundError
    }
  };
}

// Check if customer data exists
if (!inputData.data) {
  // Return a flag indicating no customer exists
  return {
    json: {
      customerExists: false,
      message: "No customer data returned from NetSuite"
    }
  };
}

try {
  // Parse the JSON string from the data field
  const customerData = JSON.parse(inputData.data);

  // Extract and flatten the important customer information
  const flattenedCustomer = {
    // IDs and Basic Info
    internalId: customerData.id,
    externalId: customerData.externalId,
    entityId: customerData.entityId,
    customerId: customerData.custentity4,

    // Personal Info
    firstName: customerData.firstName,
    lastName: customerData.lastName,
    isPerson: customerData.isPerson,
    email: customerData.email,

    // Address
    defaultAddress: customerData.defaultAddress,

    // Status and Settings
    isInactive: customerData.isInactive,
    entityStatus: {
      id: customerData.entityStatus.id,
      name: customerData.entityStatus.refName
    },

    // Financial Info
    balance: customerData.balance,
    overdueBalance: customerData.overdueBalance,
    daysOverdue: customerData.daysOverdue,
    depositBalance: customerData.depositBalance,
    unbilledOrders: customerData.unbilledOrders,

    // Aging
    aging: customerData.aging,
    aging1: customerData.aging1,
    aging2: customerData.aging2,
    aging3: customerData.aging3,
    aging4: customerData.aging4,

    // Currency
    currency: {
      id: customerData.currency.id,
      code: customerData.currency.refName
    },

    // Subsidiary
    subsidiary: {
      id: customerData.subsidiary.id,
      name: customerData.subsidiary.refName
    },

    // Accounts
    receivablesAccount: {
      id: customerData.receivablesAccount.id,
      name: customerData.receivablesAccount.refName
    },
    drAccount: {
      id: customerData.drAccount.id,
      name: customerData.drAccount.refName
    },

    // Dates
    dateCreated: customerData.dateCreated,
    lastModifiedDate: customerData.lastModifiedDate,

    // Preferences
    emailPreference: customerData.emailPreference.refName,
    emailTransactions: customerData.emailTransactions,
    printTransactions: customerData.printTransactions,
    unsubscribe: customerData.unsubscribe,

    // Shipping
    shippingCarrier: customerData.shippingCarrier.refName,
    shipComplete: customerData.shipComplete,

    // Custom Fields
    customFields: {
      customerRefund: customerData.custentity_2663_customer_refund,
      directDebit: customerData.custentity_2663_direct_debit,
      customerProbability: customerData.custentity_atlas_customer_probability,
      orderLeadTime: customerData.custentity_c360_entity_order_lead_time,
      needsApproval: customerData.custentity_naw_trans_need_approval
    }
  };

  // Return the flattened data with customerExists flag
  return { 
    json: {
      customerExists: true,
      flattenedCustomer,
      originalData: customerData
    }
  };

} catch (error) {
  // If parsing fails, return error flag
  return {
    json: {
      customerExists: false,
      message: "Error parsing customer data",
      error: error.message
    }
  };
}

const payment = $('get_payments_zoho').item.json.payment;
const invoice = $('Get Specific Invoice from Zoho Billing').item.json.invoice;
const customer = $('flat_customer').item.json.flattenedCustomer;

function formatPaymentMonth(dateString) {
  if (!dateString) return '';
  const date = new Date(dateString);
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${months[date.getMonth()]} ${date.getFullYear()}`;
}

const paymentMonth = formatPaymentMonth(payment.date);

const netsuitePayload = {
  customer: {
    id: customer.internalId
  },
  payment: payment.amount,
  tranDate: payment.date,
  tranId: `${payment.payment_id}`,
  account: {
    id: "122"
  },
  subsidiary: {
    id: "1"
  },
  currency: {
    id: customer.currency.id
  },
  memo: `Zoho Payment for ${paymentMonth}`,
  externalId: `${payment.payment_id}`,
  custbody5: payment.reference_number
  // NO apply here — will be patched after creation
};

return {
  json: {
    payload: netsuitePayload,
    invoice_number: invoice.invoice_number,  // passed forward for PATCH step
    payment_amount: payment.amount,
    reference_data_from_previous_nodes: {
      zoho_payment_id: payment.payment_id,
      zoho_payment_number: payment.payment_number,
      zoho_invoice_id: invoice.invoice_id,
      zoho_invoice_number: invoice.invoice_number,
      customer_name: invoice.customer_name,
      customer_external_id: customer.externalId,
      netsuite_customer_id: customer.internalId,
      payment_amount: payment.amount,
      payment_date: payment.date,
      payment_mode: payment.payment_mode,
      currency: customer.currency.code,
      zoho_reference_number: payment.reference_number
    }
  }
};

const items = $input.all();

if (!items || items.length === 0) {
  return [
    {
      json: {
        success: false,
        error: true,
        errorType: 'NO_INPUT',
        friendlyMessage: 'No input received from Create Payment node',
        actionableSteps: 'Check Create Payment node connection.',
        paymentContext: {
          zoho_payment_id: '',
          zoho_payment_number: '',
          customer_name: '',
          payment_amount: 0,
          invoice_number: '',
        },
      },
    },
  ];
}

function getPaymentReference() {
  try {
    const previousItems = $items('Create Payload to Create Payment in Netsuite');
    const previousJson = previousItems?.[0]?.json || {};

    return previousJson.reference_data_from_previous_nodes || {
      zoho_payment_id: previousJson.payload?.externalId || '',
      zoho_payment_number: '',
      customer_name: '',
      payment_amount: previousJson.payment_amount || previousJson.payload?.payment || 0,
      zoho_invoice_number: previousJson.invoice_number || '',
    };
  } catch (error) {
    return {
      zoho_payment_id: '',
      zoho_payment_number: '',
      customer_name: '',
      payment_amount: 0,
      zoho_invoice_number: '',
    };
  }
}

function buildPaymentContext(paymentReference) {
  return {
    zoho_payment_id: paymentReference.zoho_payment_id || '',
    zoho_payment_number: paymentReference.zoho_payment_number || '',
    customer_name: paymentReference.customer_name || '',
    payment_amount: Number(paymentReference.payment_amount || 0),
    invoice_number: paymentReference.zoho_invoice_number || '',
  };
}

return items.map((item) => {
  const input = item.json || {};
  const paymentReference = getPaymentReference();
  const paymentContext = buildPaymentContext(paymentReference);

  // NetSuite successful create sometimes returns empty object
  const isEmptyObject =
    input &&
    typeof input === 'object' &&
    !Array.isArray(input) &&
    Object.keys(input).length === 0;

  if (isEmptyObject) {
    return {
      json: {
        success: true,
        error: false,
        errorType: '',
        friendlyMessage: 'Payment created successfully in NetSuite',
        actionableSteps: '',
        technicalDetails: {},
        paymentContext,
      },
    };
  }

  // Error case from Create Payment node
  if (input.error) {
    const errorMessage = input.error.message || '';
    const errorStatus = input.error.status || 0;
    const errorCode = input.error.code || '';
    const errorName = input.error.name || '';

    const fullErrorText = JSON.stringify(input.error).toLowerCase();

    let errorType = 'UNKNOWN_ERROR';
    let friendlyMessage = 'Payment Creation Failed';
    let actionableSteps = 'Review NetSuite payment creation error.';

    if (
      fullErrorText.includes('already exists') ||
      fullErrorText.includes('duplicate')
    ) {
      errorType = 'DUPLICATE_PAYMENT';
      friendlyMessage = 'Payment Already Exists in NetSuite';
      actionableSteps = 'Payment already exists in NetSuite. Skipped to avoid duplicate.';
    } else if (errorStatus === 400 || fullErrorText.includes('bad request')) {
      errorType = 'BAD_REQUEST';
      friendlyMessage = 'NetSuite Bad Request';
      actionableSteps = 'NetSuite rejected the payment payload. Review required fields and values.';
    } else if (errorStatus === 401) {
      errorType = 'AUTH_ERROR';
      friendlyMessage = 'NetSuite Authentication Failed';
      actionableSteps = 'Check NetSuite OAuth credentials.';
    } else if (errorStatus === 403) {
      errorType = 'PERMISSION_ERROR';
      friendlyMessage = 'NetSuite Permission Denied';
      actionableSteps = 'Check NetSuite role permissions.';
    } else if (errorStatus === 404) {
      errorType = 'NOT_FOUND';
      friendlyMessage = 'NetSuite Record Not Found';
      actionableSteps = 'Check customer, invoice, account, subsidiary, or currency IDs.';
    }

    return {
      json: {
        success: false,
        error: true,
        errorType,
        friendlyMessage,
        actionableSteps,
        technicalDetails: {
          status: errorStatus,
          code: errorCode,
          name: errorName,
          message: errorMessage,
        },
        paymentContext,
      },
    };
  }

  // Any non-error response
  return {
    json: {
      success: true,
      error: false,
      errorType: '',
      friendlyMessage: 'Payment response did not contain an error',
      actionableSteps: '',
      technicalDetails: input,
      paymentContext,
    },
  };
});

// Get the payment data from 'Get a single payment' node
const payment = $('Get a single payment').item.json.payment;
const PAYMENT_SYNC_FIELD_ID = '6326029000010763609';
const PAYMENT_SYNC_FIELD_LABEL = 'Synced-to-NetSuite';

if (!payment) {
  throw new Error('Payment data not found from "Get a single payment" node');
}

const syncField = (payment.custom_fields || []).find(field =>
  field.customfield_id === PAYMENT_SYNC_FIELD_ID ||
  field.field_id === PAYMENT_SYNC_FIELD_ID ||
  field.api_name === 'cf_synced_to_netsuite' ||
  field.placeholder === 'cf_synced_to_netsuite'
) || {};

// Prepare the update payload with all required fields
const payload = {
  customer_id: payment.customer_id,
  payment_mode: payment.payment_mode,
  amount: payment.amount,
  date: payment.date,
  reference_number: payment.reference_number,
  description: payment.description || '',
  invoices: (payment.invoices || []).map(inv => ({
    invoice_id: inv.invoice_id,
    amount_applied: inv.amount_applied
  })),
  custom_fields: [
    {
      customfield_id: PAYMENT_SYNC_FIELD_ID,
      label: PAYMENT_SYNC_FIELD_LABEL,
      value: true  // Mark as processed/synced to NetSuite
      // Zoho validates the label string exactly when one is sent.
      // PAYMENT_SYNC_FIELD_LABEL must match the field label in Zoho.
      // The backend api name cf_synced_to_netsuite is unchanged.
    }
  ]
};

// Optional: Add other fields if they exist in the original payment
if (payment.exchange_rate) {
  payload.exchange_rate = payment.exchange_rate;
}

if (payment.bank_charges) {
  payload.bank_charges = payment.bank_charges;
}

if (payment.tax_account_id) {
  payload.tax_account_id = payment.tax_account_id;
}

if (payment.account_id) {
  payload.account_id = payment.account_id;
}

const originalValue = payment.custom_field_hash?.cf_synced_to_netsuite_unformatted ?? syncField.value ?? null;

return {
  json: {
    payment_id: payment.payment_id,
    payload: payload,
    debug_info: {
      payment_sync_customfield_id: PAYMENT_SYNC_FIELD_ID,
      payment_sync_field_label: PAYMENT_SYNC_FIELD_LABEL,
      original_custom_field_value: originalValue,
      new_custom_field_value: true,
      payment_number: payment.payment_number,
      customer_name: payment.customer_name,
      amount: payment.amount
    }
  }
};

const items = [];

for (const item of $input.all()) {
  const payments = item.json.payments || [];
  for (const payment of payments) {
    items.push({ json: payment });
  }
}

return items;

const staticData = $getWorkflowStaticData('global');
const items = $input.all();

// Always overwrite — never carry rows from a previous run/retry
staticData.paymentReport = {
  startedAt: new Date().toISOString(),
  runId: `RUN_${Date.now()}`,
  rows: [],
  totalExpected: items.length,
};

return items;

const staticData = $getWorkflowStaticData('global');

if (!staticData.paymentReport) {
  staticData.paymentReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

let payment = {};
try {
  payment = $('get_payments_zoho').item.json.payment || {};
} catch (error) {}

const logRow = {
  paymentId: payment.payment_id || '',
  paymentNumber: payment.payment_number || '',
  invoiceNumber: '',
  customerName: payment.customer_name || '',
  customerNumber: payment.contact_number || '',
  referenceNumber: payment.reference_number || '',
  amount: payment.amount || 0,
  status: 'ERROR',
  category: 'Zoho Invoice Error',
  stage: 'Get Specific Invoice from Zoho Billing',
  message: $json.friendlyMessage || $json.errorMessage || 'Zoho invoice was not found or invoice fetch failed.',
  technicalDetails: $json.originalError || $json,
  date: new Date().toISOString(),
};

staticData.paymentReport.rows.push(logRow);

return [
  {
    json: {
      ...$json,
      processingStatus: 'ERROR',
      reportCategory: 'Zoho Invoice Error',
      parent: {
        workflowName: 'Zoho to NetSuite Payment Automation',
        status: 'ERROR',
        stage: 'Get Specific Invoice from Zoho Billing',
        paymentId: logRow.paymentId,
        paymentNumber: logRow.paymentNumber,
      },
      child: logRow,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

if (!staticData.paymentReport) {
  staticData.paymentReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

let payment = {};
let invoice = {};

try {
  payment = $('get_payments_zoho').item.json.payment || {};
} catch (error) {}

try {
  invoice = $('Get Specific Invoice from Zoho Billing').item.json.invoice || {};
} catch (error) {}

const logRow = {
  paymentId: payment.payment_id || '',
  paymentNumber: payment.payment_number || '',
  invoiceNumber: invoice.invoice_number || '',
  customerName: invoice.customer_name || payment.customer_name || '',
  customerNumber: invoice.contact_number || payment.contact_number || '',
  referenceNumber: payment.reference_number || '',
  amount: payment.amount || 0,
  status: 'ERROR',
  category: 'Customer Lookup Error',
  stage: 'Check if Customer Exists in NetSuite',
  message: $json.friendlyMessage || 'Customer was not found in NetSuite or customer lookup failed.',
  technicalDetails: $json.originalError || $json,
  date: new Date().toISOString(),
};

staticData.paymentReport.rows.push(logRow);

return [
  {
    json: {
      ...$json,
      processingStatus: 'ERROR',
      reportCategory: 'Customer Lookup Error',
      parent: {
        workflowName: 'Zoho to NetSuite Payment Automation',
        status: 'ERROR',
        stage: 'Check if Customer Exists in NetSuite',
        paymentId: logRow.paymentId,
        paymentNumber: logRow.paymentNumber,
      },
      child: logRow,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

if (!staticData.paymentReport) {
  staticData.paymentReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

const context = $json.paymentContext || {};

const errorType = $json.errorType || '';
const messageText = String($json.friendlyMessage || $json.actionableSteps || '').toLowerCase();

const isDuplicate =
  errorType === 'DUPLICATE_PAYMENT' ||
  messageText.includes('already exists') ||
  messageText.includes('duplicate');

const category = isDuplicate ? 'Skipped Duplicates' : 'Failed';
const stage = isDuplicate ? 'Duplicate Check' : 'Payment Creation';

const invoiceNumber = context.invoice_number || '';
const customerName = context.customer_name || '';
let customerNumber = '';
try { customerNumber = $('flat_customer').item.json.flattenedCustomer.entityId || ''; } catch (e) {}
let referenceNumber = '';
try { referenceNumber = $('get_payments_zoho').item.json.payment.reference_number || ''; } catch (e) {}
const amount = Number(context.payment_amount || 0);

const logMessage = isDuplicate
  ? `Payment already exists in NetSuite for invoice ${invoiceNumber}. Skipped to avoid duplicate.`
  : ($json.friendlyMessage || 'Payment could not be created in NetSuite.');

const logRow = {
  paymentId: context.zoho_payment_id || '',
  paymentNumber: context.zoho_payment_number || '',
  invoiceNumber,
  customerName,
  customerNumber,
  referenceNumber,
  amount,
  status: isDuplicate ? 'SKIPPED' : 'ERROR',
  category,
  stage,
  message: logMessage,
  actionableSteps: $json.actionableSteps || '',
  technicalDetails: $json.technicalDetails || $json,
  errorType,
  date: new Date().toISOString(),
};

staticData.paymentReport.rows.push(logRow);

return [
  {
    json: {
      ...$json,
      processingStatus: isDuplicate ? 'SKIPPED' : 'ERROR',
      reportCategory: category,
      parent: {
        workflowName: 'Zoho to NetSuite Payment Automation',
        status: isDuplicate ? 'SKIPPED' : 'ERROR',
        stage,
        paymentId: logRow.paymentId,
        paymentNumber: logRow.paymentNumber,
      },
      child: logRow,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

if (!staticData.paymentReport) {
  staticData.paymentReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

let reference = {};

try {
  reference = $('Create Payload to Create Payment in Netsuite').item.json.reference_data_from_previous_nodes || {};
} catch (error) {}

let customerNumber = '';
try { customerNumber = $('flat_customer').item.json.flattenedCustomer.entityId || ''; } catch (e) {}

const logRow = {
  paymentId: reference.zoho_payment_id || '',
  paymentNumber: reference.zoho_payment_number || '',
  invoiceNumber: reference.zoho_invoice_number || '',
  customerName: reference.customer_name || '',
  customerNumber,
  amount: reference.payment_amount || 0,
  status: 'SUCCESS',
  category: 'Payment Synced',
  stage: 'Zoho Payment Updated',
  message: `Payment ${reference.zoho_payment_number || ''} synced successfully to NetSuite.`,
  technicalDetails: $json,
  date: new Date().toISOString(),
};

staticData.paymentReport.rows.push(logRow);

return [
  {
    json: {
      ...$json,
      processingStatus: 'SUCCESS',
      reportCategory: 'Payment Synced',
      parent: {
        workflowName: 'Zoho to NetSuite Payment Automation',
        status: 'SUCCESS',
        stage: 'Zoho Payment Updated',
        paymentId: logRow.paymentId,
        paymentNumber: logRow.paymentNumber,
      },
      child: logRow,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

// Read all processed rows directly from the loop's done-branch input items
const allItems = $input.all();
const rawRows = allItems
  .map(item => item.json.child || null)
  .filter(row => row !== null && (row.paymentId || row.paymentNumber || row.invoiceNumber));

// Use startedAt recorded at initialization
const report = staticData.paymentReport || { startedAt: new Date().toISOString() };
const startedAt = report.startedAt || new Date().toISOString();

function normalizeCategory(row) {
  const msg = String(row.message || row.friendlyMessage || '').toLowerCase();
  const errorType = String(row.errorType || row.technicalDetails?.errorType || '').toUpperCase();
  const category = String(row.category || '').toLowerCase();

  if (row.status === 'SUCCESS' || category === 'payment synced') return 'Created';

  if (
    errorType === 'DUPLICATE_PAYMENT' ||
    category.includes('skipped duplicate') ||
    category === 'already synced' ||
    msg.includes('already exists') ||
    msg.includes('duplicate')
  ) return 'Skipped Duplicates';

  if (
    category.includes('invoice') ||
    (msg.includes('invoice') && msg.includes('not found')) ||
    msg.includes('nonexistent_external_id')
  ) return 'Invoice Missing in NetSuite';

  return 'Failed';
}

function normalizeStage(row, c) {
  if (row.stage) return row.stage;
  if (c === 'Skipped Duplicates') return 'Duplicate Check';
  if (c === 'Invoice Missing in NetSuite') return 'Invoice Lookup';
  if (c === 'Created') return 'Zoho Payment Updated';
  return 'Workflow Processing';
}

const CATEGORY_PRIORITY = { 'Created': 4, 'Skipped Duplicates': 3, 'Invoice Missing in NetSuite': 2, 'Failed': 1 };
function priorityOf(c) { return CATEGORY_PRIORITY[c] || 0; }

const uniqueMap = new Map();
for (const row of rawRows) {
  const c = normalizeCategory(row);
  const s = normalizeStage(row, c);
  const key = String(row.paymentId || row.paymentNumber || row.invoiceNumber || '').trim();
  if (!key) continue;
  const existing = uniqueMap.get(key);
  if (!existing || priorityOf(c) > priorityOf(existing.normalizedCategory)) {
    uniqueMap.set(key, { ...row, normalizedCategory: c, stage: s });
  }
}

const normalizedRows = Array.from(uniqueMap.values());

const completedAt = new Date().toISOString();

const totalReportedPayments = normalizedRows.length;
const paymentsCreated = normalizedRows.filter(r => r.normalizedCategory === 'Created').length;
const skippedDuplicates = normalizedRows.filter(r => r.normalizedCategory === 'Skipped Duplicates').length;
const invoiceMissing = normalizedRows.filter(r => r.normalizedCategory === 'Invoice Missing in NetSuite').length;
const failed = normalizedRows.filter(r => r.normalizedCategory === 'Failed').length;

const totalAmount = normalizedRows.reduce((sum, r) => sum + Number(r.amount || 0), 0);

const workflowStatus =
  failed > 0 || invoiceMissing > 0 || skippedDuplicates > 0
    ? 'Completed with Exceptions'
    : 'Completed';

const parentExternalId = `PAYMENT_RUN_${Date.now()}`;

const summaryMessage =
  `Payment Automation completed. ` +
  `Total: ${totalReportedPayments}, ` +
  `Created: ${paymentsCreated}, ` +
  `Invoice missing: ${invoiceMissing}, ` +
  `Skipped duplicate: ${skippedDuplicates}, ` +
  `Failed: ${failed}.`;

const parentPayload = {
  externalId: parentExternalId,
  name: `Payment Automation Report - ${completedAt}`,
  custrecordcustrecordpar_status: workflowStatus,
  custrecordcustrecordpar_started: startedAt,
  custrecordcustrecordpar_completed: completedAt,
  custrecordcustrecordpar_total: Number(totalReportedPayments),
  custrecordcustrecordpar_recorded: Number(paymentsCreated),
  custrecordcustrecordpar_missing: Number(invoiceMissing),
  custrecordcustrecordpar_skipped: Number(skippedDuplicates),
  custrecordcustrecordpar_failed: Number(failed),
  custrecordcustrecordpar_amount: Number(totalAmount),
  custrecordcustrecordpar_summary: summaryMessage,
};

// Reset AFTER reading so the next run starts clean (prevents cross-run bleed)
staticData.paymentReport = { startedAt: new Date().toISOString(), rows: [] };

return [
  {
    json: {
      parentPayload,
      parentExternalId,
      reportRows: normalizedRows,
      debug: { rawRowsCount: rawRows.length, uniqueRowsCount: normalizedRows.length },
    },
  },
];

// Check if we have an error in the response
const inputData = $input.first().json;

// Check if error exists
if (inputData.error) {
  // Extract error details
  const errorMessage = inputData.error.message || 'Unknown error';
  const errorDescription = inputData.error.description || '';

  // Create human-friendly message based on error type
  let friendlyMessage = '';

  if (errorMessage.includes('could not be found') || errorDescription.includes('does not exist')) {
    friendlyMessage = 'Invoice does not exist in Zoho. Please verify the invoice ID and try again.';
  } else if (errorMessage.includes('unauthorized') || errorMessage.includes('authentication')) {
    friendlyMessage = 'Authentication failed. Please check your Zoho credentials.';
  } else if (errorMessage.includes('rate limit')) {
    friendlyMessage = 'Rate limit exceeded. Please wait a moment and try again.';
  } else {
    friendlyMessage = `Error: ${errorMessage}`;
  }

  return {
    json: {
      success: false,
      error: true,
      friendlyMessage: friendlyMessage,
      originalError: {
        message: errorMessage,
        description: errorDescription,
        timestamp: inputData.error.timestamp
      }
    }
  };
}

// If no error, return success
return {
  json: {
    success: true,
    error: false,
    data: inputData
  }
};

const input = $input.first().json;

// Check if we have an error
if (input.error) {
  const errorMessage = input.error.message || '';
  const errorCode = input.error.code || '';
  const errorStatus = input.error.status || 0;

  let friendlyMessage = '';
  let errorType = '';

  // Parse NetSuite-specific errors
  if (errorStatus === 500 || errorCode === 'ERR_BAD_RESPONSE') {
    // Try to extract NetSuite error details from the message
    try {
      const match = errorMessage.match(/Error ID: ([a-z0-9]+)/);
      const errorId = match ? match[1] : 'unknown';

      friendlyMessage = `NetSuite Internal Server Error\n\nThe customer lookup failed in NetSuite. This usually means:\n• The customer with this external ID doesn't exist in NetSuite\n• NetSuite is experiencing temporary issues\n\nError ID: ${errorId}\n\nPlease verify the customer exists in NetSuite or try again later.`;
      errorType = 'NETSUITE_INTERNAL_ERROR';
    } catch (e) {
      friendlyMessage = 'NetSuite Internal Server Error. The customer may not exist in NetSuite or there is a temporary issue.';
      errorType = 'NETSUITE_ERROR';
    }
  } else if (errorStatus === 404 || errorMessage.includes('could not be found')) {
    friendlyMessage = 'Customer not found in NetSuite. Please verify the external ID exists.';
    errorType = 'NOT_FOUND';
  } else if (errorMessage.includes('unauthorized') || errorStatus === 401) {
    friendlyMessage = 'Authentication failed. Please check your NetSuite credentials.';
    errorType = 'AUTH_ERROR';
  } else if (errorStatus === 429) {
    friendlyMessage = 'Rate limit exceeded. Please wait and try again.';
    errorType = 'RATE_LIMIT';
  } else {
    friendlyMessage = `An error occurred: ${errorMessage.substring(0, 200)}`;
    errorType = 'UNKNOWN_ERROR';
  }

  return {
    json: {
      success: false,
      error: true,
      errorType: errorType,
      friendlyMessage: friendlyMessage,
      originalError: {
        message: errorMessage,
        code: errorCode,
        status: errorStatus
      }
    }
  };
}

// If no error, return success
return {
  json: {
    success: true,
    error: false,
    data: input
  }
};

