const lookupRaw = $input.first().json || {};
let lookupResponse = lookupRaw;
if (typeof lookupRaw.data === 'string') {
  lookupResponse = JSON.parse(lookupRaw.data);
} else if (lookupRaw.body && typeof lookupRaw.body === 'string') {
  lookupResponse = JSON.parse(lookupRaw.body);
} else if (lookupRaw.body && typeof lookupRaw.body === 'object') {
  lookupResponse = lookupRaw.body;
} else if (lookupRaw.data && typeof lookupRaw.data === 'object') {
  lookupResponse = lookupRaw.data;
}
const items =
  lookupResponse.items ||
  lookupResponse.body?.items ||
  lookupResponse.data?.items ||
  lookupRaw.items ||
  [];
const parentId =
  items?.[0]?.id ||
  items?.[0]?.ID ||
  lookupResponse.id ||
  lookupRaw.id;
if (!parentId) {
  throw new Error(
    'Parent NetSuite report ID was not found from lookup. Actual input was: ' +
    JSON.stringify(lookupRaw)
  );
}
const parentData = $('Prepare NetSuite Parent Report Payload').first().json || {};
const uniqueRows = parentData.reportRows || [];
function cleanText(value, maxLength = 300) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}
function getCategory(row) {
  return row.normalizedCategory || row.category || 'Failed';
}
// Only log exception lines — do NOT show successfully created payments
const exceptionRows = uniqueRows.filter(row => getCategory(row) !== 'Created');
return exceptionRows.map(row => {
  const category = getCategory(row);
  const invoiceNum = row.invoiceNumber || '';
  const paymentRef = row.paymentId || row.paymentNumber || '';
  const customerNum = row.customerNumber || row.customerName || '';
  const amount = Number(row.amount || 0);
  const recordName = invoiceNum
    ? `${invoiceNum} - ${category}`
    : `${paymentRef} - ${category}`;
  const childPayload = {
    name: cleanText(recordName, 80),
    custrecordcustrecordpal_report: { id: String(parentId) },
    custrecordcustrecordpal_category: cleanText(category, 300),
    custrecordcustrecordpal_invoice: cleanText(invoiceNum, 300),
    custrecordcustrecordpal_customer: cleanText(customerNum, 300),
    custrecordcustrecordpal_amount: amount,
    custrecordcustrecordpal_extref: cleanText(paymentRef, 300),
    custrecordcustrecordpal_stage: cleanText(row.stage || 'Workflow Processing', 300),
    custrecordcustrecordpal_message: cleanText(row.message || '', 1000),
    custrecordcustrecordpal_totalpayment: amount,
    custrecord155: cleanText(row.customerNumber || '', 300),
  };
  // Gateway Transaction ID (custrecord156) — Integer Number field, sourced from Zoho reference_number.
  // Only set when reference_number is a valid integer; omit otherwise to avoid NetSuite type errors.
  const refInt = parseInt(row.referenceNumber, 10);
  if (Number.isFinite(refInt)) {
    childPayload.custrecord156 = refInt;
  }
  return {
    json: {
      childPayload,
      parentId: String(parentId),
    },
  };
});

// Aggregate validation across ALL invoices tagged on the payment.
// Rule: fail the WHOLE payment if ANY invoice is missing OR has zero open balance.
// Otherwise apply capped amount = min(zoho_applied, netsuite_remaining) per invoice.

const lookups  = $input.all();                          // NetSuite lookup results (per invoice, in order)
const expanded = $('Expand Payment Invoices').all();    // source invoice rows (in order)
const paymentAmount = Number($('get_payments_zoho').item.json.payment.amount || 0);

const applyItems = [];
const failures = [];
let anyMissing = false;

for (let i = 0; i < expanded.length; i++) {
  const src = expanded[i].json || {};
  const invoiceNumber = src.invoice_number;
  const zohoApplied = Number(src.zoho_applied || 0);

  if (src._noInvoices) {
    failures.push('Payment has no tagged invoices in Zoho.');
    anyMissing = true;
    continue;
  }

  const raw = (lookups[i] && lookups[i].json) || {};
  let invoice = raw;
  try {
    if (typeof raw.data === 'string') invoice = JSON.parse(raw.data);
    else if (raw.data && typeof raw.data === 'object') invoice = raw.data;
    else if (typeof raw.body === 'string') invoice = JSON.parse(raw.body);
    else if (raw.body && typeof raw.body === 'object') invoice = raw.body;
  } catch (e) { invoice = {}; }

  const internalId = invoice && invoice.id;

  // CASE 1: invoice not found in NetSuite -> fail whole payment
  if (raw.error || !internalId) {
    failures.push(`Invoice ${invoiceNumber || '(unknown)'} does not exist in NetSuite.`);
    anyMissing = true;
    continue;
  }

  const rawRemaining = invoice.amountRemaining ?? invoice.amountremaining ?? invoice.amountDue ?? invoice.amountdue;
  const amountRemaining = Number(rawRemaining ?? 0);

  // CASE 2: no open balance -> fail whole payment
  if (amountRemaining <= 0) {
    failures.push(`Invoice ${invoiceNumber} has no open balance in NetSuite (amountRemaining=${rawRemaining ?? 'n/a'}).`);
    continue;
  }

  // CASE 3: OK -> apply capped amount
  const applyAmount = Math.min(zohoApplied > 0 ? zohoApplied : amountRemaining, amountRemaining);
  applyItems.push({ doc: { externalId: String(invoiceNumber) }, apply: true, amount: applyAmount });
}

const invoiceValid = failures.length === 0 && applyItems.length > 0;

return [{
  json: {
    invoiceValid,
    invoiceStatus: invoiceValid ? 'OK' : (anyMissing ? 'MISSING' : 'FULLY_PAID'),
    applyItems,
    paymentAmount,
    totalApplied: applyItems.reduce((s, x) => s + x.amount, 0),
    failures,
    message: invoiceValid
      ? `All ${applyItems.length} invoice(s) valid. Payment will be created and applied.`
      : `Payment NOT created. Issues: ${failures.join(' ')}`,
  },
  pairedItem: { item: 0 }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.paymentReport) {
  staticData.paymentReport = { startedAt: new Date().toISOString(), rows: [] };
}

let payment = {};
let invoice = {};
try { payment = $('get_payments_zoho').item.json.payment || {}; } catch (e) {}
try { invoice = $('Get Specific Invoice from Zoho Billing').item.json.invoice || {}; } catch (e) {}

const status = $json.invoiceStatus || 'MISSING';
const isMissing = status === 'MISSING';
const isDuplicate = status === 'DUPLICATE';

const category = isDuplicate ? 'Skipped Duplicates' : (isMissing ? 'Invoice Missing in NetSuite' : 'Failed');
const stage = isDuplicate ? 'Duplicate Check' : (isMissing ? 'Invoice Lookup' : 'Invoice Already Paid');
const logStatus = isDuplicate ? 'SKIPPED' : 'ERROR';
const message = $json.message ||
  (isDuplicate
    ? 'Payment was already synced to NetSuite. Skipping as duplicate.'
    : isMissing
    ? 'Invoice does not exist in NetSuite. Payment was NOT created.'
    : 'Invoice already fully paid in NetSuite. Payment was NOT created.');

let customerNumber = payment.contact_number || '';
try { customerNumber = $('flat_customer').item.json.flattenedCustomer.entityId || customerNumber; } catch(e) {}

const logRow = {
  paymentId: payment.payment_id || '',
  paymentNumber: payment.payment_number || '',
  invoiceNumber: invoice.invoice_number || '',
  customerName: invoice.customer_name || payment.customer_name || '',
  customerNumber,
