const paymentId = paymentData.payment_id || '';
const paymentNumber = paymentData.payment_number || '';
const invoiceNumber = paymentData.invoice_number || (paymentData.invoices && paymentData.invoices[0] && paymentData.invoices[0].invoice_number) || '';
const customerName = paymentData.customer_name || '';
const customerNumber = paymentData.contact_number || '';
const referenceNumber = paymentData.reference_number || '';
