};

staticData.paymentReport.rows.push(logRow);

return [{ json: logRow }];

const raw = $input.first().json || {};
const originalStatus = $('Check Invoice Status').item.json;

// NetSuite GET responses arrive wrapped as { data: "<json string>" } / { body: ... }.
// Parse every variant so we can read the payment record id.
let parsed = raw;
try {
  if (typeof raw.data === 'string') parsed = JSON.parse(raw.data);
  else if (raw.data && typeof raw.data === 'object') parsed = raw.data;
  else if (typeof raw.body === 'string') parsed = JSON.parse(raw.body);
  else if (raw.body && typeof raw.body === 'object') parsed = raw.body;
} catch (e) {
  parsed = {};
}

const hasError = !!raw.error;
// A found payment has a record id (or tranId). 404 (not found) comes back as raw.error.
const paymentFound = !hasError && (parsed.id != null || parsed.tranId != null);

if (paymentFound) {
  const payment = $('get_payments_zoho').item.json.payment || {};
  const zohoPaymentId = payment.payment_id || '';
  const zohoPaymentNumber = payment.payment_number || '';
  return [{
    json: {
      ...originalStatus,
      invoiceStatus: 'DUPLICATE',
      invoiceValid: false,
      message: 'Payment #' + zohoPaymentNumber + ' (ID: ' + zohoPaymentId + ') was already synced to NetSuite. Skipping as duplicate.',
    }
  }];
} else {
  return [{
    json: {
      ...originalStatus,
    }
  }];
}

// Fan out: one output item per invoice tagged on the Zoho payment.
const payment = $('get_payments_zoho').item.json.payment || {};
const invoices = Array.isArray(payment.invoices) ? payment.invoices : [];

if (invoices.length === 0) {
  // No tagged invoices -> single sentinel item so validation can fail cleanly
  return [{ json: { invoice_number: null, invoice_id: null, zoho_applied: 0, _noInvoices: true } }];
}

return invoices.map(inv => ({
  json: {
    invoice_number: inv.invoice_number,
    invoice_id: inv.invoice_id,
    // Zoho field-name variants for the amount applied to THIS invoice
    zoho_applied: Number(inv.amount_applied ?? inv.applied_amount ?? inv.amount ?? 0),
  }
}));
